🤖 [Qwen Edge] Certainly! Below is an example of how to implement a singly and doubly linked lists in C++. The code includes the necessary structures for both types of lists, as well as functions to create nodes and insert them into the list.

```cpp
#include <iostream>
using namespace std;

// Singly Linked List Node structure
struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

// Doubly Linked List Node structure
struct DoubleListNode {
    int value;
    DoubleListNode* prev;
    DoubleListNode* next;
    DoubleListNode(int x, DoubleListNode* p = nullptr, DoubleListNode* n = nullptr)
        : value(x), prev(p), next(n) {}
};

// Function to create a singly linked list
void createSinglyLinkedList(ListNode*& head, int data) {
    ListNode* newNode = new ListNode(data);
    if (!head) {
        head = newNode;
    } else {
        while (head->next) {
            head = head->next;
        }
        head->next = newNode;
    }
}

// Function to traverse and print a singly linked list
void printSinglyLinkedList(ListNode* head) {
    while (head != nullptr) {
        cout << head->val << " ";
        head = head->next;
    }
}

// Function to create a doubly linked list
void createDoubleLinkedList(DoubleListNode*& head, int data) {
    DoubleListNode* newNode = new DoubleListNode(data);
    if (!head) {
        head = newNode;
    } else {
        newNode->prev = head->prev;
        newNode->next = head;
        head->prev->next = newNode;
        head->prev = newNode;
    }
}

// Function to traverse and print a doubly linked list
void printDoubleLinkedList(DoubleListNode* head) {
    while (head != nullptr) {
        cout << head->value << " ";
        head = head->next;
    }
}
```

### Explanation

1. **Singly Linked List:**
   - The `ListNode` structure is used to represent each node in the singly linked list.
   - The `createSinglyLinkedList` function creates a new node with the provided data and either links it to an existing head (if one exists) or at the beginning of the list if there's no existing head.

2. **Doubly Linked List:**
   - The `DoubleListNode` structure is used to represent each node in the doubly linked list.
   - The `createDoubleLinkedList` function creates a new node with the provided data and either links it between an existing pair of nodes (if such pairs exist) or at the beginning/end of the list if there's no previous/next node.

3. **Printing:**
   - The `printSinglyLinkedList` and `printDoubleLinkedList` functions traverse each linked list in order, printing their values from head to tail.

### Usage Example

```cpp
int main() {
    ListNode* head = nullptr;  // Singly Linked List

    createSinglyLinkedList(head, 3);     // Create a node with value 3
    createSinglyLinkedList(head, 5);
    createSinglyLinkedList(head, 7);

    printSinglyLinkedList(head);          // Print the singly linked list

    DoubleListNode* head2 = nullptr;      // Doubly Linked List

    createDoubleLinkedList(head2, 4);      // Create a node with value 4
    createDoubleLinkedList(head2, 6);

    printDoubleLinkedList(head2);           // Print the doubly linked list

    return 0;
