fn calculate_mean(numbers: &mut Vec<f64>) -> f64 {
    if numbers.is_empty() {
        return 0.0;
    }

    let mut total = 0f64;
    for num in numbers.iter_mut().flatten() {
        total += *num as f64;
    }

    total / numbers.len() as f64
}

fn main() {
    let mut data = vec![1.0, 2.0, 3.0];

    // Call the function and print the result
    println!("{}", calculate_mean(&mut data));
}
```

